import {searchMembers,memberBalance,memberFunds,memberLedger} from './members.js';
import {moneyInput} from './workbench.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'¥'+(n/100).toFixed(2),$=s=>document.querySelector(s);
const field=(id,label,props='')=>`<label class="field owner-field">${label}<input id="${id}" ${props}></label>`;
const highlight=(text,query)=>{const q=query.trim().toLowerCase();if(!q)return esc(text);let out='',start=0,index;while((index=text.toLowerCase().indexOf(q,start))!==-1){out+=esc(text.slice(start,index))+'<mark class="search-match">'+esc(text.slice(index,index+q.length))+'</mark>';start=index+q.length;}return out+esc(text.slice(start));};
const amount=id=>moneyInput($(id).value||'0');
export function createMemberUI(ctx){let selected=null,query='',archived=false,visibleLimit=100;
 async function edit(member){const create=!member,transactionId=crypto.randomUUID(),id=member?.id||crypto.randomUUID();
 const body=field('member-name','名字',`required maxlength="80" value="${esc(member?.name||'')}"`)+field('member-phone','手机号码',`type="tel" inputmode="tel" required pattern="[0-9]{6,20}" value="${esc(member?.phone||'')}"`)+(create?paymentFields('首充金额（30元起）'): '');
 const ok=await ctx.formDialog(create?'新建会员与首充':'修改会员信息',body,async()=>{await ctx.act({type:'member:'+(create?'create':'edit'),id,transactionId,name:$('#member-name').value,phone:$('#member-phone').value,...(create?{amount:amount('#member-amount'),gift:amount('#member-gift'),note:$('#member-note').value}:{})});selected=id;},'保存',create?giftHook:undefined);if(ok){render();ctx.toast('会员信息已保存');}}
 function paymentFields(label){return field('member-amount',label,'type="number" step="0.01" min="0" inputmode="decimal" placeholder="0.00" required')+field('member-gift','赠送金额（默认充值的10%，可修改）','type="number" step="0.01" min="0" inputmode="decimal" placeholder="0.00"')+field('member-note','备注（可留空）','maxlength="500"')+'<p class="help">充值与赠送一并计入可用余额；金额保存后写入不可重复执行的流水。</p>';}
 function giftHook(){
  let manual=false;
  $('#member-gift').oninput=()=>{manual=true;};
  $('#member-amount').oninput=()=>{if(manual)return;try{$('#member-gift').value=(Math.round(amount('#member-amount')/10)/100).toFixed(2);}catch{$('#member-gift').value='';}};
 }
 async function payment(m,type){const transactionId=crypto.randomUUID();const body=type==='recharge'?paymentFields('续充金额（10元起）'):field('member-amount','消费金额',`type="number" step="0.01" min="0.01" max="${(memberBalance(m)/100).toFixed(2)}" inputmode="decimal" required placeholder="0.00"`)+field('member-note','消费备注（可留空）','maxlength="500"');
 const ok=await ctx.formDialog(type==='recharge'?'会员续充':'记录会员消费',`<p>${esc(m.name)} · ${esc(m.phone)}<br>可用余额 ${money(memberBalance(m))}</p>`+body,()=>ctx.act({type:'member:'+type,id:m.id,transactionId,amount:amount('#member-amount'),gift:type==='recharge'?amount('#member-gift'):0,note:$('#member-note').value}),'确认保存',type==='recharge'?giftHook:undefined);if(ok){render();ctx.toast(type==='recharge'?'充值成功':'消费已记录');}}
 async function refund(m,deleteAfter=false){
  const f=memberFunds(m),transactionId=crypto.randomUUID();
  const body=`<p><b data-user-text>${esc(m.name)}</b> · ${esc(m.phone)}</p><div class="notice">按本店规则可退实付金额：<b>${money(f.refundable)}</b><br>同时清空赠金：<b>${money(f.gift)}</b><br>操作后可用余额为0。${deleteAfter?'此会员将退出正常搜索，历史流水保留归档。':''}</div><p class="help">此处只登记退款，不会自动转账；请核对金额并线下实际退还会员。</p>`+field('refund-note','退款／清零备注（可留空）','maxlength="500"')+`<label class="check-field"><input id="refund-confirm" type="checkbox" required> ${f.paid>0?'已线下退还上述实付金额，并确认清空赠金':'确认清空剩余赠金'}</label>`;
  const ok=await ctx.formDialog(deleteAfter?'退款／清零并删除会员':'登记退款并清空赠金',body,()=>ctx.act({type:'member:refund',id:m.id,transactionId,amount:f.paid,gift:f.gift,deleteAfter,note:$('#refund-note').value}),deleteAfter?'确认退款／清零并删除':'确认登记退款');
  if(ok){if(deleteAfter)selected=null;render();ctx.toast(deleteAfter?'退款／清零已登记，会员已归档':'退款已登记，赠金已清空');}
 }
 async function remove(m){const f=memberFunds(m);if(!await ctx.ask('确认删除这位会员？',`${m.name} · ${m.phone}。${f.total?'需先退还实付余额 '+money(f.paid)+' 并清空赠金 '+money(f.gift)+'，下一步核对实际退款。':'余额为0。'}删除后不再参与正常搜索，充值、消费和退款记录仍保留在已删除会员中。`,{danger:true,label:f.total?'继续核对退款／清零':'确认删除'}))return;if(f.total){await refund(m,true);return;}await ctx.act({type:'member:delete',id:m.id});selected=null;render();ctx.toast('会员已删除，历史流水已归档');}
 function render(){if(!ctx.staff()){ctx.content.innerHTML='<section class="card">请先切换到店员模式</section>';return;}if(ctx.mode()==='sandbox'){ctx.content.innerHTML='<section class="card">会员操作只在正式模式使用，请退出测试模式。</section>';return;}
 const all=ctx.state().members||[],rows=all.filter(m=>archived?!!m.deletedAt:!m.deletedAt),m=all.find(m=>m.id===selected);const funds=m?memberFunds(m):null;
 ctx.content.innerHTML=ctx.heading('会员管理','首充30元起 · 续充10元起 · 赠送默认10%',`<div class="member-page-actions"><button class="primary" id="member-create">＋ 新建会员</button>${m?'':`<div class="member-archive-controls"><button id="member-archive" class="secondary">${archived?'返回正常会员':'查看已删除会员'}</button><span class="badge">${archived?'已删除会员（只读）':'正常会员'}</span></div>`}</div>`)+
 (m?`<section class="card member-detail-card"><div class="action-row"><button id="member-back" class="secondary">← 返回搜索</button>${m.deletedAt?'':'<button id="member-edit" class="secondary">修改信息</button>'}</div><h2 data-user-text>${esc(m.name)}</h2><p>${esc(m.phone)}${m.deletedAt?' · 已删除（历史只读）':''}</p><div class="member-balance-hero"><div class="money-metric"><small>剩余可用金额</small><strong>${money(memberBalance(m))}</strong></div><div class="money-metric refundable-metric"><small>可退金额</small><strong>${money(funds.refundable)}</strong></div></div><div class="member-balance-secondary"><div class="money-metric"><small>实付余额</small><strong>${money(funds.paid)}</strong></div><div class="money-metric"><small>赠金余额</small><strong>${money(funds.gift)}</strong></div><div class="money-metric"><small>累计充值</small><strong>${money(m.transactions.filter(t=>t.type==='recharge').reduce((n,t)=>n+t.amount,0))}</strong></div><div class="money-metric"><small>累计赠送</small><strong>${money(m.transactions.filter(t=>t.type==='recharge').reduce((n,t)=>n+t.gift,0))}</strong></div></div><p class="help">消费先扣实付余额，不足部分再扣赠金；退款按剩余实付金额计算，并清空全部赠金。</p><div class="action-row member-primary-actions" ${m.deletedAt?'hidden':''}><button id="member-recharge" class="primary">充值</button><button id="member-spend" class="secondary" ${memberBalance(m)<=0?'disabled':''}>记录消费</button></div><div class="member-danger-actions" ${m.deletedAt?'hidden':''}><button id="member-refund" class="secondary" ${funds.total<=0?'disabled':''}>登记退款／清空赠金</button><button id="member-delete" class="danger">删除会员</button></div></section><section class="card mode-card"><h2>充值、消费与退款记录</h2>${memberLedger(m).reverse().map(t=>`<div class="member-ledger"><b>${t.type==='recharge'?'充值 '+money(t.amount)+' · 赠送 '+money(t.gift):t.type==='refund'?'退实付 '+money(t.amount)+' · 清空赠金 '+money(t.gift):'消费 −'+money(t.amount)}</b><small>${ctx.stamp(t.at)}</small>${t.type==='spend'?`<small>扣实付 ${money(t.paidUsed)} · 扣赠金 ${money(t.giftUsed)}</small>`:''}<span data-user-text>${esc(t.note)}</span></div>`).join('')}</section>`:
 `<section class="card member-list-card"><label class="field">搜索姓名、手机号码或尾号<input id="member-search" type="search" autocomplete="off" placeholder="留空显示全部会员，输入即可搜索" value="${esc(query)}"></label><p class="help member-search-help">按姓名排序；数字搜索优先匹配手机尾号。</p><div id="member-results"></div><button id="member-load-more" class="secondary" hidden>加载更多会员</button></section><p class="help member-list-footer">${archived?'已删除会员':'正常会员'}共 ${rows.length} 位，数据保存在本机，随完整JSON备份导出。</p>`);
 ctx.content.querySelector('.page-heading').classList.toggle('member-list-heading',!m);
 $('#member-create').onclick=()=>ctx.safe(()=>edit());
 if(m){$('#member-back').onclick=()=>{selected=null;render();};if(!m.deletedAt){$('#member-delete').onclick=()=>ctx.safe(()=>remove(m));$('#member-refund').onclick=()=>ctx.safe(()=>refund(m));$('#member-edit').onclick=()=>ctx.safe(()=>edit(m));}if($('#member-recharge'))$('#member-recharge').onclick=()=>ctx.safe(()=>payment(m,'recharge'));$('#member-spend').onclick=()=>ctx.safe(()=>payment(m,'spend'));}
 else {$('#member-archive').onclick=()=>{archived=!archived;query='';visibleLimit=100;render();};const list=()=>{const matches=searchMembers(archived?rows.map(m=>({...m,deletedAt:undefined})):rows,query);$('#member-results').innerHTML=matches.slice(0,visibleLimit).map(m=>`<button class="member-result" data-member="${esc(m.id)}"><b data-user-text>${highlight(m.name,query)}</b><span data-user-text>${highlight(m.phone,query)}</span></button>`).join('')||`<p class="empty">${query.trim()?'暂无匹配会员':archived?'暂无已删除会员':'暂无会员，点击右上角新建会员'}</p>`;const more=$('#member-load-more');more.hidden=matches.length<=visibleLimit;more.textContent=`加载更多会员（已显示 ${Math.min(visibleLimit,matches.length)} / ${matches.length}）`;more.onclick=()=>{visibleLimit+=100;list();};document.querySelectorAll('[data-member]').forEach(b=>b.onclick=()=>{$('#member-search').blur();selected=b.dataset.member;render();});};$('#member-search').oninput=e=>{query=e.target.value;visibleLimit=100;list();};list();}
 }
 return {render};
}
